# vite.config.ts:  import tailwindcss from "@tailwindcss/vite";  plugins: [tailwindcss()]
# src/index.css:
@import "tailwindcss";

.center {
  display: grid;
  place-items: center;
  min-height: 100vh;
}

.layout {
  display: grid;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
}
.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.footer  { grid-area: footer; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}

.row {
  display: flex;
  flex-direction: row;          /* column for vertical */
  justify-content: space-between; /* main axis */
  align-items: center;          /* cross axis */
  flex-wrap: wrap;
  gap: 1rem;
}
.grow { flex: 1; }              /* take remaining space */

:root {
  --bg: #ffffff;
  --text: #111111;
  --accent: #2457d6;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #0e1116; --text: #e6e9ee; }
}
body { background: var(--bg); color: var(--text); }

@media (min-width: 768px) { /* tablets and up */ }
@media (min-width: 1024px) { /* desktops */ }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; } }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
